ciphertext = "xpcg{v6v37rp96k79}"
key = "SECAUTOMIND"

# Map letters to numbers (A=0, B=1, ..., Z=25)
def char_to_num(c):
    return ord(c.upper()) - ord('A')

def num_to_char(n):
    return chr(n % 26 + ord('A'))

# Decrypt
key_index = 0
plaintext = []

for char in ciphertext:
    if char.isalpha():
        # Decrypt: P = (C - K) mod 26
        c_num = char_to_num(char)
        k_num = char_to_num(key[key_index % len(key)])
        p_num = (c_num - k_num) % 26
        plaintext.append(num_to_char(p_num))
        key_index += 1
    else:
        plaintext.append(char)

print(''.join(plaintext))

